export function summarizeRetailInvoice(lines = []) {
  let raw = 0;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line && line.qty > 0 && line.unitPrice > 0) {
      raw += line.qty * line.unitPrice;
    }
  }
  const subtotal = Math.round(raw * 100) / 100;
  const tax = Math.round(subtotal * 0.13 * 100) / 100;
  const total = Math.round((subtotal + tax) * 100) / 100;
  return {tier: 'retail', subtotal, tax, total};
}

export function summarizeWholesaleInvoice(lines = []) {
  let raw = 0;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line && line.qty > 0 && line.unitPrice > 0) {
      raw += line.qty * line.unitPrice;
    }
  }
  const subtotal = Math.round(raw * 100) / 100;
  const tax = Math.round(subtotal * 0.09 * 100) / 100;
  const total = Math.round((subtotal + tax) * 100) / 100;
  return {tier: 'wholesale', subtotal, tax, total};
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {summarizeRetailInvoice, summarizeWholesaleInvoice} from '../src/invoice.mjs';

test('retail and wholesale invoice calculation', () => {
  const lines = [{qty: 2, unitPrice: 19.99}, {qty: 0, unitPrice: 100}, {qty: 1, unitPrice: 10.02}];
  assert.deepEqual(summarizeRetailInvoice(lines), {tier: 'retail', subtotal: 50, tax: 6.5, total: 56.5});
  assert.deepEqual(summarizeWholesaleInvoice(lines), {tier: 'wholesale', subtotal: 50, tax: 4.5, total: 54.5});
});

export function canAccessDocument(user, doc, action) {
  if (user && !user.disabled) {
    if (doc && !doc.deleted) {
      if (user.role === 'admin') {
        return {allowed: true, reason: 'ADMIN'};
      } else {
        if (action === 'read') {
          if (doc.isPublic || doc.ownerId === user.id) {
            return {allowed: true, reason: 'READ_OK'};
          } else {
            return {allowed: false, reason: 'FORBIDDEN'};
          }
        } else if (action === 'write') {
          if (doc.ownerId === user.id && !doc.locked) {
            return {allowed: true, reason: 'WRITE_OK'};
          } else {
            return {allowed: false, reason: 'FORBIDDEN'};
          }
        } else {
          return {allowed: false, reason: 'UNKNOWN_ACTION'};
        }
      }
    } else {
      return {allowed: false, reason: 'DOC_UNAVAILABLE'};
    }
  } else {
    return {allowed: false, reason: 'USER_INVALID'};
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {canAccessDocument} from '../src/access.mjs';

test('all branches of canAccessDocument', () => {
  assert.deepEqual(canAccessDocument(null, {}, 'read'), {allowed: false, reason: 'USER_INVALID'});
  assert.deepEqual(canAccessDocument({id: 1, disabled: true}, {}, 'read'), {allowed: false, reason: 'USER_INVALID'});
  assert.deepEqual(canAccessDocument({id: 1}, {deleted: true}, 'read'), {allowed: false, reason: 'DOC_UNAVAILABLE'});
  assert.deepEqual(canAccessDocument({id: 1, role: 'admin'}, {ownerId: 2}, 'write'), {allowed: true, reason: 'ADMIN'});
  assert.deepEqual(canAccessDocument({id: 1}, {ownerId: 2, isPublic: true}, 'read'), {allowed: true, reason: 'READ_OK'});
  assert.deepEqual(canAccessDocument({id: 1}, {ownerId: 1, locked: false}, 'write'), {allowed: true, reason: 'WRITE_OK'});
  assert.deepEqual(canAccessDocument({id: 1}, {ownerId: 1, locked: true}, 'write'), {allowed: false, reason: 'FORBIDDEN'});
  assert.deepEqual(canAccessDocument({id: 1}, {ownerId: 1}, 'delete'), {allowed: false, reason: 'UNKNOWN_ACTION'});
});
